  "prediction_basis_card_ids": [
    "C15","C39","C12","C52","C10","C61","C84","C82","C72",
    "C110","C118","C133","C143","C121",
    "C126","C129","C148","C174","C158",
    "C183","C192","C206","C181","C190","C184","C191","C165",
    "C195","C160","C204","C175","C161","C182","C176"
  ],
  "claims": [
    {
      "claim": "Direct absolute oral bioavailability measurements for polar nucleoside analogs in L1/L2 are all at or above the 20% threshold: zalcitabine 80% in fasted HIV patients (C15) and 30% in fasted mice (C39); ddA/ddI 38% in fasting patients (C12) and ddI 30–54% (C52); OGT719 about 25% in patients (C10). The query is a carbocyclic guanine nucleoside lacking the acid-labile N-glycosidic bond of ddA/ddI, so these values support F ≥ 20%.",
      "card_ids": ["C15","C39","C12","C52","C10"]
    },
    {
      "claim": "L3 oral exposure records for entecavir, a carbocyclic guanine nucleoside, show rapid oral absorption (Tmax 0.63–1.0 h; C61, C84), and oral famciclovir produces measurable penciclovir exposure (C82, C72). No L3 record affirmatively indicates F < 20%.",
      "card_ids": ["C61","C84","C82","C72"]
    },
    {
      "claim": "L4 solubility/dissolution evidence for related nucleosides is favorable: ribavirin high solubility (C110, C118), ganciclovir 2.6 mg/mL (C133), aciclovir fast dissolution (C143), and AZT >90% GI absorption (C121). Low passive permeability records are not affirmative low-F evidence because didanosine PAMPA 0.11×10^-6 cm/s (C126) coexists with measured F 30–54% (C52), and penciclovir/tenofovir records (C129, C148, C174, C158) are for different scaffolds.",
      "card_ids": ["C110","C118","C133","C143","C121","C126","C129","C148","C174","C158","C52"]
    },
    {
      "claim": "L5 gut-wall evidence shows that nucleoside transporters mediate intestinal uptake of related nucleosides: cladribine via ENT/CNT (C183, C192, C206), gemcitabine via nucleoside transporters (C181), ribavirin via CNT3 (C190), and trifluridine via CNT1 (C184). Lamivudine is not a BCRP substrate and shows no basal ABC-transporter efflux (C191, C165).",
      "card_ids": ["C183","C192","C206","C181","C190","C184","C191","C165"]
    },
    {
      "claim": "Gut-wall efflux observed for related nucleosides is not affirmative evidence of F < 20%: BCRP efflux for abacavir (C195, C160, C204, C175) and cladribine (C161, C182), and ddI secretory efflux (C176), coexist with oral bioavailability at or above the threshold in those or closely related nucleoside contexts (C15, C39, C12, C52).",
      "card_ids": ["C195","C160","C204","C175","C161","C182","C176","C15","C39","C12","C52"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "gut_wall_efflux_intestinal_metabolism",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": [
        "C183","C192","C206","C181","C190","C184","C191","C165",
        "C195","C160","C204","C175","C161","C182","C176","C174","C158"
      ]
    }
  ],
  "evidence_gaps": [
    "No direct measured absolute oral bioavailability for the exact query molecule.",
    "No human pharmacokinetic data for the cyclobutyl bis(hydroxymethyl)guanine scaffold.",
    "No direct intestinal metabolism or deamination data for the query; L5 records are predominantly transport assays.",
    "Formulation and dose are not specified beyond the fasted state.",
    "The magnitude of BCRP/efflux or nucleoside-transporter affinity for the query is not directly measured."
  ],
  "decision_summary": "L5 gut-wall evidence is mechanistically mixed but not threshold-negative: nucleoside transporters support intestinal uptake of related analogs, while BCRP/secretory efflux for abacavir, cladribine, and ddI coexists with F ≥ 20% in those contexts. Combined with direct F ≥ 20% for polar nucleosides, favorable solubility/dissolution, and oral exposure records, the prediction remains high with moderate confidence."
}

